package vn.edu.eaut.lab5.ui;
import vn.edu.eaut.lab5.bus.DanhMucBUS; import vn.edu.eaut.lab5.model.DanhMuc; import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*; import java.util.List;
public class DanhMucPanel extends JPanel {private final DanhMucBUS bus=new DanhMucBUS();private final JTextField id=new JTextField(),name=new JTextField(),search=new JTextField();private final DefaultTableModel m=new DefaultTableModel(new Object[]{"Mã","Tên danh mục"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable t=new JTable(m);private final JButton add=new JButton("Thêm"),edit=new JButton("Sửa"),del=new JButton("Xóa"),ref=new JButton("Làm mới"),find=new JButton("Tìm kiếm");
 public DanhMucPanel(){setLayout(new BorderLayout(8,8));setBorder(BorderFactory.createEmptyBorder(10,10,10,10));id.setEditable(false);JPanel f=new JPanel(new GridLayout(2,2,8,8));f.add(new JLabel("Mã danh mục:"));f.add(id);f.add(new JLabel("Tên danh mục:"));f.add(name);JPanel a=new JPanel(new FlowLayout(FlowLayout.LEFT));for(JButton b:new JButton[]{add,edit,del,ref})a.add(b);JPanel q=new JPanel(new BorderLayout(5,0));q.add(new JLabel("Tìm:"),BorderLayout.WEST);q.add(search);q.add(find,BorderLayout.EAST);JPanel top=new JPanel(new BorderLayout(5,5));top.add(f,BorderLayout.NORTH);top.add(a,BorderLayout.CENTER);top.add(q,BorderLayout.SOUTH);add(top,BorderLayout.NORTH);add(new JScrollPane(t));t.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);add.addActionListener(e->save(true));edit.addActionListener(e->save(false));del.addActionListener(e->delete());ref.addActionListener(e->{clear();load("");});find.addActionListener(e->load(search.getText()));t.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()){int r=t.getSelectedRow();if(r>=0){id.setText(m.getValueAt(r,0).toString());name.setText(m.getValueAt(r,1).toString());}}});load("");}
 private void load(String s){new SwingWorker<List<DanhMuc>,Void>(){protected List<DanhMuc> doInBackground()throws Exception{return s.isBlank()?bus.findAll():bus.search(s);}protected void done(){try{m.setRowCount(0);for(DanhMuc x:get())m.addRow(new Object[]{x.getMaDm(),x.getTenDm()});}catch(Exception e){error(e);}}}.execute();}private void save(boolean n){try{DanhMuc x=new DanhMuc(n?0:Integer.parseInt(id.getText()),name.getText().trim());if(bus.save(x)){clear();load("");}}catch(Exception e){error(e);}}private void delete(){try{if(!id.getText().isBlank()&&bus.delete(Integer.parseInt(id.getText()))){clear();load("");}}catch(Exception e){error(e);}}private void clear(){id.setText("");name.setText("");t.clearSelection();}private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Lỗi",JOptionPane.ERROR_MESSAGE);}}
